Game.States.Menu.prototype = {
	create: function(){
		// Background
		this.background = this.game.add.tileSprite(0, 0, 480, 320, 'background');
		this.background.autoScroll(-150, -20);
		this.background.tilePosition.x = Game.backgroundX;
		this.background.tilePosition.y = Game.backgroundY;

		// Btn Play
		this.btnPlayGroup = this.game.add.group();

		this.btnPlay = this.game.add.button(0, 0, 'btnMenu', this.menuAnimOut, this, 1, 0, 1, 0);
		this.btnPlayGroup.add(this.btnPlay);

		this.btnPlayText = this.game.add.bitmapText(this.game.width/2, 12, 'kenpixelblocks', 'Play', 20);
		this.btnPlayText.x = this.btnPlay.width/2 - this.btnPlayText.textWidth/2;
		this.btnPlayGroup.add(this.btnPlayText);

		this.btnPlayGroup.x = this.game.width/2 - this.btnPlay.width/2;
		this.btnPlayGroup.y = 190;
		this.btnPlayGroup.alpha = 0;

		// Btn More
		this.btnMoreGroup = this.game.add.group();

		this.btnMore = this.game.add.button(0, 0, 'btnMenu', this.moreGames, this, 1, 0, 1, 0);
		this.btnMoreGroup.add(this.btnMore);

		this.btnMoreText = this.game.add.bitmapText(this.game.width/2, 12, 'kenpixelblocks', 'More games', 20);
		this.btnMoreText.x = this.btnMore.width/2 - this.btnMoreText.textWidth/2;
		this.btnMoreGroup.add(this.btnMoreText);

		this.btnMoreGroup.x = this.game.width/2 - this.btnPlay.width/2;
		this.btnMoreGroup.y = 250;
		this.btnMoreGroup.alpha = 0;

		// Title
		this.title = this.game.add.sprite(this.game.width/2, 0, 'title');
		this.title.anchor.setTo(0.5, 0);
		this.title.alpha = 0;

		// Tween
		this.game.add.tween(this.btnPlayGroup).to({alpha:1, y: 150}, 600, Phaser.Easing.Exponential.Out, true);
		this.game.add.tween(this.btnMoreGroup).to({alpha:1, y: 210}, 600, Phaser.Easing.Exponential.Out, true, 200);
		this.game.add.tween(this.title).to({alpha: 1, y:40}, 600, Phaser.Easing.Exponential.Out, true);
	},

	menuAnimOut: function(){
		// Tween
		this.game.add.tween(this.btnPlayGroup).to({alpha:0}, 600, Phaser.Easing.Exponential.Out, true);
		this.game.add.tween(this.btnMoreGroup).to({alpha:0}, 600, Phaser.Easing.Exponential.Out, true);
		this.game.add.tween(this.title).to({alpha: 0, y:10}, 600, Phaser.Easing.Exponential.Out, true);

		this.timerInit = this.game.time.create(true);
		this.timerInit.add(Phaser.Timer.SECOND*0.8, this.startGame, this);
		this.timerInit.start();

	},

	startGame: function(){
		// Store background scroll position
		Game.backgroundX = this.background.tilePosition.x;
		Game.backgroundY = this.background.tilePosition.y;

		this.game.state.start('Play');
	},

	moreGames: function(){
		window.open('http://www.loopeex.com/html5-games/', '_blank');
	}
};Game.States.Play = function(game){
	this.BONUS_DURATION = 6; // In seconds

	this.background;
	this.hero;

	this.btnPause;
	this.pausePanel;

	this.gameoverPanel;

	this.bullets;
	this.lastBulletShotAt;

	this.enemies;
	this.enemiesGenerator;
	this.lasers;
	this.lasersGenerator;

	this.timerInit;

	this.livesGroup;
	this.livesNum;
	this.livesTween;

	this.score;
	this.scoreText;

	this.level;

	this.bonus;

	this.gameover;

	this.juicy;
	this.screenFlash;
};

Game.States.Play.prototype = {
	create: function(){
		// Background
		this.background = this.game.add.tileSprite(0, 0, 480, 320, 'background');
		this.background.autoScroll(-150, -20);
		this.background.tilePosition.x = Game.backgroundX;
		this.background.tilePosition.y = Game.backgroundY;
		this.game.add.tween(this.background).to({alpha: 0.2}, 5000, Phaser.Easing.Linear.NONE, true, 0, Number.POSITIVE_INFINITY, true);

		// Bullets group
		this.bullets = this.game.add.group();

		// Enemies
		this.enemies = this.game.add.group();

		// Enemies lasers
		this.lasers = this.game.add.group();

		// Bonus
		this.bonus = this.game.add.group();

		// Level
		this.level = 1;

		// Gameover
		this.gameover = false;

		// Hero
		this.hero = new Game.Prefabs.Hero(this.game, -45, this.game.height/2, this.game.input);
		this.game.add.existing(this.hero);
		this.game.add.tween(this.hero).to({x:60}, 1500, Phaser.Easing.Exponential.Out, true);

		// Button pause
		this.btnPause = this.game.add.button(10, 10, 'btn', this.pauseGame, this, 1, 0, 1, 0);
		this.btnPause.alpha = 0;

		// Pause panel
		this.pausePanel = new Game.Prefabs.PausePanel(this.game);
		this.game.add.existing(this.pausePanel);

		// Gameover panel
		this.gameoverPanel = new Game.Prefabs.GameoverPanel(this.game);
		this.game.add.existing(this.gameoverPanel);

		// Display lives
		this.livesGroup = this.game.add.group();
		this.livesGroup.add(this.game.add.sprite(0, 0, 'lives'));
		this.livesGroup.add(this.game.add.sprite(20, 3, 'num', 0));
		this.livesNum = this.game.add.sprite(35, 3, 'num', this.hero.lives+1);
		this.livesGroup.add(this.livesNum);
		this.livesGroup.x = this.game.width - 55;
		this.livesGroup.y = 5;
		this.livesGroup.alpha = 0;

		// Juicy
		this.juicy = this.game.plugins.add(Phaser.Plugin.Juicy);
		this.screenFlash = this.juicy.createScreenFlash();
		this.add.existing(this.screenFlash);

		// Score
		this.score = 0;
		this.scoreText = this.game.add.bitmapText(10, this.game.height - 27, 'kenpixelblocks', 'Score : 0', 16);
		this.scoreText.alpha = 0;

		// Enter play mode after init state
		this.timerInit = this.game.time.create(true);
		this.timerInit.add(Phaser.Timer.SECOND*1.5, this.initGame, this);
		this.timerInit.start();

		// FPS
		this.game.time.advancedTiming = true;
	    this.fpsText = this.game.add.text(
	        410, 290, '', { font: '16px Arial', fill: '#ffffff' }
	    );
	},

	update: function(){
		var bullet;

		if(!Game.paused){
			this.shootBullet();
			this.checkCollisions();
		}

		this.fpsText.setText(this.game.time.fps + ' FPS');
	},

	shutdown: function(){
		this.bullets.destroy();
		this.enemies.destroy();
		this.lasers.destroy();
		this.hero.destroy();
		this.pausePanel.destroy();
		this.gameoverPanel.destroy();
		Game.paused = true;
	},

	initGame: function(){
		// Generate enemies
		this.enemiesGenerator = this.game.time.events.add(3000, this.generateEnemies, this);

		// Generate enemies laser
		this.lasersGenerator = this.game.time.events.add(1000, this.shootLaser, this);

		// Track analytics
		Game.Analytics.trackEvent('Start', 1);

		// Show UI
		this.game.add.tween(this.livesGroup).to({alpha:1}, 600, Phaser.Easing.Exponential.Out, true);
		this.game.add.tween(this.scoreText).to({alpha:1}, 600, Phaser.Easing.Exponential.Out, true);

		// Play
		this.playGame();
	},

	pauseGame: function(){
		if(!Game.paused){
			Game.paused = true;
			this.hero.follow = false;

			// Pause enemies generator
			this.enemiesGenerator.timer.pause();

			// Freeze enemies
			this.enemies.forEach(function(group){
				group.callAll('pause');
			}, this);

			// Freeze lasers rotation
			this.lasers.forEach(function(laser){
				laser.pause();
			}, this);

			// Hide pause button
			this.game.add.tween(this.btnPause).to({alpha:0}, 600, Phaser.Easing.Exponential.Out, true);

			if(!this.gameover){
				// Show pause panel
				this.pausePanel.show();
			}
		}
	},

	playGame: function(){
		if(Game.paused){
			Game.paused = false;

			// Active ship following pointer
			this.hero.follow = true;
			this.hero.body.collideWorldBounds = true;

			// Resume enemies generator
			this.enemiesGenerator.timer.resume();

			// Active lasers rotation
			this.lasers.forEach(function(laser){
				laser.resume();
			}, this);

			// Restart follow position
			this.game.input.x = this.hero.x;
			this.game.input.y = this.hero.y;

			// Show pause button
			this.game.add.tween(this.btnPause).to({alpha:1}, 600, Phaser.Easing.Exponential.Out, true);
		}
	},

	goToMenu: function(){
		// Save background scroll
		Game.backgroundX = this.background.tilePosition.x;
		Game.backgroundY = this.background.tilePosition.y;

		this.game.state.start('Menu');
	},

	shootBullet: function(){
		// Check delay time
		if(this.lastBulletShotAt === undefined) this.lastBulletShotAt = 0;
		if(this.game.time.now - this.lastBulletShotAt < this.hero.shotDelay){
			return;
		}
		this.lastBulletShotAt = this.game.time.now;

		// Create bullets
		var bullet, bulletPosY;
		for(var i=-1; i<this.hero.numBullets; i+=2){
			bullet = this.bullets.getFirstExists(false);
			if(!bullet){
				bullet = new Game.Prefabs.Bullet(this.game, 0, 0);
				this.bullets.add(bullet);
			}

			bulletPosY = this.hero.y;
			if(this.hero.numBullets > 1){
				bulletPosY = this.hero.y - ((this.hero.height-5)/2)*i;
			}

			bullet.reset(this.hero.x+10, bulletPosY);
		}
	},

	generateEnemies: function(){
		var enemies = this.enemies.getFirstExists(false);

		if(!enemies){
			enemies = new Game.Prefabs.Enemies(this.game, this.enemies);
		}
		// reset(fromY, toY, speed)
		enemies.reset(this.game.rnd.integerInRange(50, 270), this.game.rnd.integerInRange(50, 270), 150 + this.level*10 + this.game.rnd.integerInRange(0, 10));

		// Relaunch timer depending on level
		this.enemiesGenerator = this.game.time.events.add(this.game.rnd.integerInRange(12, 20)*250/this.level, this.generateEnemies, this);
	},

	shootLaser: function(){
		var laser = this.lasers.getFirstExists(false);

		if(!laser){
			laser = new Game.Prefabs.Laser(this.game, 0, 0);
			this.lasers.add(laser);
		}
		laser.reset(this.game.width + laser.width/2, this.game.rnd.integerInRange(20, this.game.height-20));
		laser.reload(100 + this.level*30);

		// Relaunch bullet timer depending on level
		this.lasersGenerator = this.game.time.events.add(this.game.rnd.integerInRange(12, 20)*500/this.level, this.shootLaser, this);
	},

	checkCollisions: function(){
		// Enemies vs Bullets
		this.enemies.forEach(function(enemy){
			this.game.physics.arcade.overlap(this.bullets, enemy, this.killEnemy, null, this);
		}, this);

		// Hero vs Enemies
		this.enemies.forEach(function(enemy){
			this.game.physics.arcade.overlap(this.hero, enemy, this.killHero, null, this);
		}, this);

		// Hero vs Lasers
		this.game.physics.arcade.overlap(this.hero, this.lasers, this.killHero, null, this);

		// Hero vs Bonus
		this.game.physics.arcade.overlap(this.hero, this.bonus, this.activeBonus, null, this);
	},

	killEnemy: function(bullet, enemy){
		if(!enemy.dead && enemy.checkWorldBounds){
			enemy.die();
			bullet.kill();
			this.updateScore();
		}
	},

	killHero: function(hero, enemy){
		if(enemy instanceof Game.Prefabs.Laser || (enemy instanceof Game.Prefabs.Enemy && !enemy.dead && enemy.checkWorldBounds)){
			if(!this.hero.shielded){
				// Update lives
				this.hero.lives--;
				this.screenFlash.flash();

				if(this.hero.lives < 1){
					this.gameOver();
				}else{
					this.hero.enableShield(2);

					// Anim remaining lives
					this.game.add.tween(this.livesNum).to({alpha:0, y: 8}, 200, Phaser.Easing.Exponential.Out, true).onComplete.add(function(){
						this.livesNum.frame = this.hero.lives+1;
						this.livesNum.y = -2;
						this.game.add.tween(this.livesNum).to({alpha:1, y:3}, 200, Phaser.Easing.Exponential.Out, true);
					}, this);
				}
			}else{
				enemy.die(true);	// Like an autokill if killed with shield : no bonus
			}
		}
	},

	addBonus: function(enemy){
		var bonus = this.bonus.getFirstDead();
		var type = this.game.rnd.integerInRange(0, 1);
		
		if(!bonus){
			bonus = new Game.Prefabs.Bonus(this.game, 0, 0, type);
			this.bonus.add(bonus);
		}

		bonus.reload(enemy.x, enemy.y, type);
	},

	activeBonus: function(hero, bonus){
		bonus.kill();

		switch(bonus.type){
			case 1: 
				// Double shoot
				hero.enableDoubleShoot(this.BONUS_DURATION);
				break;
			default:
				// Shield
				hero.enableShield(this.BONUS_DURATION);
				break;
		}
	},

	updateScore: function(){
		this.score += 10;
		this.scoreText.setText('Score : ' + this.score.toString());

		// Level depending on player score
		if(this.score < 500){
			this.changeLevel(1);
		}else if(this.score < 1500){
			this.changeLevel(2);
		}else if(this.score < 3000){
			this.changeLevel(3);
		}else if(this.score < 5000){
			this.changeLevel(4);
		}else if(this.score < 10000){
			this.changeLevel(5);
		}
	},

	changeLevel: function(level){
		if(this.level !== level){
			this.level = level;
		}
	},

	gameOver: function(){
		// Gamover
		this.gameover = true;

		// Shake screen
		this.juicy.shake(20, 5);

		// Kill hero
		this.game.add.tween(this.hero).to({alpha:0}, 500, Phaser.Easing.Exponential.Out, true);

		// Hide UI
		this.scoreText.alpha = 0;
		this.livesGroup.alpha = 0;

		// Pause game
		this.pauseGame();

		// Show gameover panel
		this.gameoverPanel.show(this.score);

		// Track analytics
		Game.Analytics.trackEvent('Score', this.score);
	}
};Game.Prefabs.Bonus = function(game, x, y, frame, type){
	// Super call to Phaser.sprite
	Phaser.Sprite.call(this, game, x, y, 'bonus', frame);

	// Centered anchor
	this.anchor.setTo(0.5, 0.5);

	// Kill when out of world
	this.checkWorldBounds = true;
	this.outOfBoundsKill = true;

	// Enable physics
	this.game.physics.enable(this, Phaser.Physics.ARCADE);

	// Type
	this.type = type;
}

Game.Prefabs.Bonus.prototype = Object.create(Phaser.Sprite.prototype);
Game.Prefabs.Bonus.constructor = Game.Prefabs.Bonus;

Game.Prefabs.Bonus.prototype.update = function(){
	if(!Game.paused){
		this.body.velocity.x = -100;
	}else{
		this.body.velocity.x = 0;
	}
};

Game.Prefabs.Bonus.prototype.reload = function(x, y, frame){
	this.x = x;
	this.y = y;
	this.frame = frame;
	this.type = frame;
	this.revive();
};Game.Prefabs.Bullet = function(game, x, y){
	// Super call to Phaser.sprite
	Phaser.Sprite.call(this, game, x, y, 'bullet');

	// Centered anchor
	this.anchor.setTo(0.5, 0.5);

	// Save vars for velocity when game is pauses
	this.savedVelocityX = 0;
	this.savedVelocityY = 0;

	// Kill when out of world
	this.checkWorldBounds = true;
	this.outOfBoundsKill = true;

	// Enable physics
	this.game.physics.enable(this, Phaser.Physics.ARCADE);
}

Game.Prefabs.Bullet.prototype = Object.create(Phaser.Sprite.prototype);
Game.Prefabs.Bullet.constructor = Game.Prefabs.Bullet;

Game.Prefabs.Bullet.prototype.update = function(){
	if(!Game.paused){
		this.body.velocity.x = 300;
	}else{
		this.body.velocity.x = 0;
	}
};Game.Prefabs.Enemies = function(game, parent){
	// Super call to Phaser.Group
	Phaser.Group.call(this, game, parent);

	// Count living enemies
	this.livingEnemies = 5;

	// Switch if kery killed all enemies of the group
	this.killedAll = true;

	var enemy;
	for(var i=0; i<5; i++){
		enemy = this.add(new Game.Prefabs.Enemy(this.game, 0, 0, 'enemy1', enemy || new Phaser.Point(0, 0)));
		enemy.x = this.game.width + enemy.width/2 + i*(enemy.width + 10);
		enemy.y = 300;
	}
};

Game.Prefabs.Enemies.prototype = Object.create(Phaser.Group.prototype);
Game.Prefabs.Enemies.constructor = Game.Prefabs.Enemies;

Game.Prefabs.Enemies.prototype.update = function(){
	this.callAll('update');
};

Game.Prefabs.Enemies.prototype.reset = function(from, to, speed){
	this.exists = true;
	this.livingEnemies = 5;
	this.killedAll = true;

	// Reset all enemies
	var i = 0;
	this.forEach(function(enemy){
		if(i === 0){
			enemy.resetTarget(to);
		}

		enemy.reload(i, from, speed);
		i++;
	}, this);
};

Game.Prefabs.Enemies.prototype.updateStatus = function(enemy, autoKill){
	this.livingEnemies--;

	if(autoKill){
		this.killedAll = false;
	}

	if(this.livingEnemies === 0){
		this.exists = false;

		// Randomly activate a bonus if killed all the enemies
		if(this.killedAll){
			var rdm = this.game.rnd.integerInRange(1, 4);
			
			if(rdm === 1){
				this.game.state.getCurrentState().addBonus(enemy);
			}
		}
	}
};Game.Prefabs.Enemy = function(game, x, y, type, target){
	// Super call to Phaser.sprite
	Phaser.Sprite.call(this, game, x, y, type);

	// Speed
	this.speed = 150;

	// Target
	this.target = target;

	// Dead - Can't use alive because enemies follow each other
	this.dead = false;

	// Min Distance
	this.minDistance = 10;

	// Explosion
	this.explosion = this.game.add.sprite(0,0,'explosion');
	this.explosion.anchor.setTo(0.5, 0.5);
	this.explosion.alpha = 0;

	// Enable physics on this object
	this.anchor.setTo(0.5, 0.5);
    this.game.physics.enable(this, Phaser.Physics.ARCADE);

    // Out of bounds callback
    this.events.onOutOfBounds.add(function(){
    	this.die(true);
    }, this);
}

Game.Prefabs.Enemy.prototype = Object.create(Phaser.Sprite.prototype);
Game.Prefabs.Enemy.constructor = Game.Prefabs.Enemy;

Game.Prefabs.Enemy.prototype.update = function(){
	if(!Game.paused){
		// Change velocity to follow the target
		var distance, rotation;
		distance = this.game.math.distance(this.x, this.y, this.target.x, this.target.y);

		if(distance > this.minDistance){
			rotation = this.game.math.angleBetween(this.x, this.y, this.target.x, this.target.y);

			this.body.velocity.x = Math.cos(rotation) * this.speed;
			this.body.velocity.y = Math.sin(rotation) * this.speed;
		}else{
			this.body.velocity.setTo(0, 0);
		}

		// Active enemy
		if(this.x < this.game.width && !this.checkWorldBounds){
			this.checkWorldBounds = true;
		}
	}
};

Game.Prefabs.Enemy.prototype.die = function(autoKill){
	if(!this.dead){
		this.dead = true;
		this.alpha = 0;

		// Explosion
		if(!autoKill){
			this.explosion.reset(this.x, this.y);
			this.explosion.angle = this.game.rnd.integerInRange(0, 360);
			this.explosion.alpha = 0;
			this.explosion.scale.x = 0.2;
			this.explosion.scale.y = 0.2;
			this.game.add.tween(this.explosion).to({alpha: 1, angle: "+30"}, 200, Phaser.Easing.Linear.NONE, true, 0).to({alpha: 0, angle: "+30"}, 300, Phaser.Easing.Linear.NONE, true, 0);
			this.game.add.tween(this.explosion.scale).to({x:1.5, y:1.5}, 500, Phaser.Easing.Cubic.Out, true, 0);
		}

		// Update parent group
		this.parent.updateStatus(this, autoKill);
	}
};

Game.Prefabs.Enemy.prototype.pause = function(){
	this.body.velocity.x = 0;
	this.body.velocity.y = 0;
};

Game.Prefabs.Enemy.prototype.reload = function(i, from, speed){
	this.x = this.game.width + this.width/2 + i*(this.width + 10);
	this.checkWorldBounds = false;
	this.dead = false;
	this.alpha = 1;
	this.speed = speed;
	this.y = from;
};

Game.Prefabs.Enemy.prototype.resetTarget = function(to){
	this.target = new Phaser.Point(-200, to);
};Game.Prefabs.GameoverPanel = function(game, parent){
	// Super call to Phaser.Group
	Phaser.Group.call(this, game, parent);

	// Add panel
	this.panel = this.game.add.sprite(0, 0, 'pausePanel');
	this.panel.width = 480;
	this.panel.height = 80;
	this.add(this.panel);

	// Pause text
	this.textPause = this.game.add.bitmapText(game.width/2, -42, 'kenpixelblocks', 'Game over', 28);
	this.textPause.position.x = this.game.width/2 - this.textPause.textWidth/2;
	this.add(this.textPause);

	// Score text
	this.textScore = this.game.add.bitmapText(game.width/2, 100, 'kenpixelblocks', 'Score : 0', 16);
	this.textScore.position.x = this.game.width/2 - this.textScore.textWidth/2;
	this.add(this.textScore);

	// Highscore text
	this.textHighScore = this.game.add.bitmapText(game.width/2, 125, 'kenpixelblocks', 'High Score : 0', 16);
	this.textHighScore.position.x = this.game.width/2 - this.textHighScore.textWidth/2;
	this.add(this.textHighScore);

	// Group pos
	this.y = -80;
	this.x = 0;
	this.alpha = 0;

	// Play button
	this.btnReplay = this.game.add.button(this.game.width/2-32, 15, 'btn', this.replay, this, 3, 2, 3, 2);
	this.btnReplay.anchor.setTo(0.5, 0);
	this.add(this.btnReplay);

	// Btn Menu
	this.btnMenu = this.game.add.button(this.game.width/2+28, 15, 'btn', function(){
		this.game.state.getCurrentState().goToMenu();
	}, this, 5, 4, 5, 4);
	this.btnMenu.anchor.setTo(0.5, 0);
	this.add(this.btnMenu);
};

Game.Prefabs.GameoverPanel.prototype = Object.create(Phaser.Group.prototype);
Game.Prefabs.GameoverPanel.constructor = Game.Prefabs.GameoverPanel;

Game.Prefabs.GameoverPanel.prototype.show = function(score){
	var highScore;
	var beated = false;
	localStorage.setItem('highScore', 0);

	this.textScore.setText('Score : ' + score.toString());

	if(!!localStorage){
		highScore = parseInt(localStorage.getItem('highScore'), 10);

		if(!highScore || highScore < score){
			highScore = score;
			localStorage.setItem('highScore', highScore);

			// Add new sprite if best score beated
			if(score > 0){
				beated = true;
				this.newScore = this.game.add.sprite(0, 132, 'new');
				this.newScore.anchor.setTo(0.5, 0.5);
				this.add(this.newScore);
			}
		}
	}else{
		highScore = 0;
	}

	this.textHighScore.setText('High Score : ' + highScore.toString());

	// Center text
	this.textScore.updateText();
	this.textScore.position.x = this.game.width/2 - this.textScore.textWidth/2;

	this.textHighScore.updateText();
	this.textHighScore.position.x = this.game.width/2 - this.textHighScore.textWidth/2;

	if(beated){
		this.newScore.x = this.textHighScore.position.x - 30;
	}

	// Show panel
	this.game.add.tween(this).to({alpha:1, y:this.game.height/2 - this.panel.height/2}, 1000, Phaser.Easing.Exponential.Out, true, 0);
};

Game.Prefabs.GameoverPanel.prototype.replay = function(){
	// Track analytics
	Game.Analytics.trackEvent('Start', 1);
	Game.Analytics.trackEvent('Restart', 1);

	// Start
	this.game.state.start('Play');
};Game.Prefabs.Hero = function(game, x, y, target){
	// Super call to Phaser.sprite
	Phaser.Sprite.call(this, game, x, y, 'hero');

	// Target : pointer
	this.target = target;

	// Follow pointer
	this.follow = false;

	// Speed
	this.speed = 200;

	// Hero lives
	this.lives = 3;

	// Hero shot delay
	this.shotDelay = 300;

	// Number of bullets per shoot
	this.numBullets = 1;
	this.timerBullet;

	// Hero shiled
	this.shielded = false;
	this.timerShield;
	this.shield = this.game.add.sprite(0, 0, 'shield');
	this.shield.anchor.setTo(0.5, 0.5);
	this.shield.alpha = 0;

	// Min distance from pointer
	this.minDistance = 10;

	// Set sprite's anchor to the center
	this.anchor.setTo(0.5, 0.5);

	// Enable physics on this object
    this.game.physics.enable(this, Phaser.Physics.ARCADE);
}

Game.Prefabs.Hero.prototype = Object.create(Phaser.Sprite.prototype);
Game.Prefabs.Hero.constructor = Game.Prefabs.Hero;

Game.Prefabs.Hero.prototype.update = function(){
	var distance, rotation;

	// Follow pointer
	if(this.follow){
		distance = this.game.math.distance(this.x, this.y, this.target.x, this.target.y);

		if(distance > this.minDistance){
			rotation = this.game.math.angleBetween(this.x, this.y, this.target.x, this.target.y);

			this.body.velocity.x = Math.cos(rotation) * this.speed * Math.min(distance / 120, 2);
			this.body.velocity.y = Math.sin(rotation) * this.speed * Math.min(distance / 120, 2);
		}else{
			this.body.velocity.setTo(0, 0);
		}
	}else{
		this.body.velocity.setTo(0, 0);
	}

	// Shield
	if(this.shielded){
		this.shield.x = this.x;
		this.shield.y = this.y;
	}

	//Check for paused and shield is active
	if(Game.paused && this.shielded) {
		this.timerShield.pause();
		console.log("Paused the sheild timer");
	}
	else if(!Game.paused && this.shielded && this.timerShield.paused) {
		this.timerShield.resume();
		console.log("Resuming shield timer");
	}
};

Game.Prefabs.Hero.prototype.enableShield = function(duration){
	this.shielded = true;

	if(this.timerShield && !this.timerShield.expired){
		this.timerShield.destroy();
	}

	this.timerShield = this.game.time.create(true);
	this.timerShield.add(Phaser.Timer.SECOND*duration, this.disabledShield, this);
	this.timerShield.start();

	// Shield anim
	this.game.add.tween(this.shield).to({alpha:1}, 300, Phaser.Easing.Cubic.Out, true, 0);
};

Game.Prefabs.Hero.prototype.disabledShield = function(){
	// Shield anim
	this.game.add.tween(this.shield)
	.to({alpha:0}, 200, Phaser.Easing.Linear.NONE, true, 0, 6, true).onComplete.add(function(){
		this.shielded = false;
	}, this);
};

Game.Prefabs.Hero.prototype.enableDoubleShoot = function(duration){
	this.numBullets = 2;

	if(this.timerBullet && !this.timerBullet.expired){
		this.timerBullet.destroy();
	}
	
	this.timerBullet = this.game.time.create(true);
	this.timerBullet.add(Phaser.Timer.SECOND*duration, this.disabledDoubleShoot, this);
	this.timerBullet.start();
};

Game.Prefabs.Hero.prototype.disabledDoubleShoot = function(){
	// Shield anim
	this.numBullets = 1;
};Game.Prefabs.Laser = function(game, x, y){
	// Super call to Phaser.sprite
	Phaser.Sprite.call(this, game, x, y, 'laser');

	// Centered anchor
	this.anchor.setTo(0.5, 0.5);

	// Speed
	this.speed = 150;

	// Kill when out of world
	this.checkWorldBounds = true;
	this.outOfBoundsKill = true;

	// Enable physics
	this.game.physics.enable(this, Phaser.Physics.ARCADE);

	this.tween = this.game.add.tween(this).to({angle:-360}, 3000, Phaser.Easing.Linear.NONE, true, 0, Number.POSITIVE_INFINITY);
}

Game.Prefabs.Laser.prototype = Object.create(Phaser.Sprite.prototype);
Game.Prefabs.Laser.constructor = Game.Prefabs.Laser;

Game.Prefabs.Laser.prototype.update = function(){
	if(!Game.paused){
		this.body.velocity.x = -this.speed;
	}else{
		this.body.velocity.x = 0;
	}
};

Game.Prefabs.Laser.prototype.reload = function(speed){
	this.alpha = 1;
	this.speed = speed;
	this.scale.x = 1;
	this.scale.y = 1;
};

Game.Prefabs.Laser.prototype.die = function(){
	this.game.add.tween(this).to({alpha: 0}, 150, Phaser.Easing.Cubic.Out, true, 0);
	this.game.add.tween(this.scale).to({x:1.5, y:1.5}, 150, Phaser.Easing.Cubic.Out, true, 0);
};

Game.Prefabs.Laser.prototype.pause = function(){
	this.tween.pause();
};

Game.Prefabs.Laser.prototype.resume = function(){
	this.tween.resume();
};Game.Prefabs.PausePanel = function(game, parent){
	// Super call to Phaser.Group
	Phaser.Group.call(this, game, parent);

	// Add panel
	this.panel = this.game.add.sprite(0, 0, 'pausePanel');
	this.panel.width = 480;
	this.panel.height = 80;
	this.add(this.panel);

	// Pause text
	this.textPause = this.game.add.bitmapText(game.width/2, -42, 'kenpixelblocks', 'Pause', 28);
	this.textPause.position.x = this.game.width/2 - this.textPause.textWidth/2;
	this.add(this.textPause);

	// Group pos
	this.y = -80;
	this.x = 0;
	this.alpha = 0;

	// Play button
	this.btnPlay = this.game.add.button(this.game.width/2-32, 15, 'btn', this.unPause, this, 3, 2, 3, 2);
	this.btnPlay.anchor.setTo(0.5, 0);
	this.add(this.btnPlay);

	// Btn Menu
	this.btnMenu = this.game.add.button(this.game.width/2+28, 15, 'btn', function(){
		this.game.state.getCurrentState().goToMenu();
	}, this, 5, 4, 5, 4);
	this.btnMenu.anchor.setTo(0.5, 0);
	this.add(this.btnMenu);
};

Game.Prefabs.PausePanel.prototype = Object.create(Phaser.Group.prototype);
Game.Prefabs.PausePanel.constructor = Game.Prefabs.PausePanel;

Game.Prefabs.PausePanel.prototype.show = function(){
	this.game.add.tween(this).to({alpha:1, y:this.game.height/2 - this.panel.height/2}, 1000, Phaser.Easing.Exponential.Out, true, 0);
};

Game.Prefabs.PausePanel.prototype.unPause = function(){
	this.game.add.tween(this).to({alpha:0, y:-80}, 1000, Phaser.Easing.Exponential.Out, true, 0);
	this.game.state.getCurrentState().playGame();
};window.onload = function(){
	// Create phaser game
	var phaser = new Phaser.Game(480, 320, Phaser.AUTO, 'game');

	// Load states
	phaser.state.add('Boot', Game.States.Boot);
	phaser.state.add('Preloader', Game.States.Preloader);
	phaser.state.add('Menu', Game.States.Menu);
	phaser.state.add('Play', Game.States.Play);

	// Load game
	phaser.state.start('Boot');
};